DAY = 11

L0 = [
  {'part': 'read'},
  "Every frontend performance problem ends up in one of two places: the **network** (bytes arrive late) or the **main thread** (the browser is too busy to respond or paint). The browser pipeline explains the second: parse, style, layout, paint, composite, all on one thread shared with your JavaScript.",
  {'h': 'A frame, in budget terms'},
  "At 60 frames per second, each frame has about 16.7 ms. The browser needs some of that for its own work, leaving roughly 10 ms for your JavaScript. A click handler that runs for 200 ms means 12 frames where nothing moves and the next interaction waits. The browser calls any task over 50 ms a **long task**; those are what hurt responsiveness (INP).",
  {'h': 'Breaking up long tasks'},
  {'ul': ['**Yield** to the browser between chunks of work (`await scheduler.yield()` where supported, or `setTimeout(0)`), so input and rendering can run in between.', '**Move work off the main thread:** parsing big JSON, diffing, image processing and search indexing can run in a Web Worker.', '**Do less:** virtualise long lists, debounce input handlers, avoid re-rendering the whole tree on every keystroke.', '**Batch DOM reads, then writes**, to avoid forced synchronous layouts (layout thrashing).']},
  {'h': 'What forces layout'},
  "Reading geometry (`offsetHeight`, `getBoundingClientRect()`, `scrollTop`, `getComputedStyle`) after changing styles forces the browser to compute layout immediately, synchronously. In a loop that alternates writes and reads, it recomputes layout on every iteration. Read everything first, then write everything.",
  {'part': 'real'},
  {'case': {'who': 'Chrome team (web.dev)', 'when': 'ongoing guidance', 'title': 'Optimizing long tasks',
    'body': ["The Chrome team's guidance on long tasks explains that any task over 50 ms blocks the main thread long enough for users to notice, and recommends breaking work into smaller tasks and yielding to the main thread, especially before work that is not visible to the user. It introduced `scheduler.yield()` as a way to yield while keeping the continuation's priority, so work resumes promptly after the browser has handled input and rendering."],
    'lesson': 'Responsiveness is about the longest task, not total work. Splitting the same work into small tasks makes the page feel fast.',
    'src': [['Optimize long tasks (web.dev)', 'https://web.dev/articles/optimize-long-tasks']]}},
  {'case': {'who': 'Paul Irish', 'when': 'maintained list', 'title': 'What forces layout and reflow',
    'body': ["Paul Irish maintains a widely referenced list of DOM properties and methods that, when read, force the browser to calculate style and layout synchronously: element dimensions, scroll positions, focus, `getComputedStyle`, `innerText` and many more. It is the reference engineers use when hunting layout thrashing."],
    'lesson': 'Know which reads are expensive. Most layout thrashing comes from innocent-looking property reads inside loops.',
    'src': [['What forces layout/reflow (gist)', 'https://gist.github.com/paulirish/5d52fb081b3570c81e3a']]}},
  {'part': 'apply'},
  {'code': "// Layout thrashing vs batching: same result, very different cost\nconst items = [...document.querySelectorAll('.card')];\n\n// Bad: write, then read (forces layout), repeated per element\nitems.forEach(el => { el.style.width = '50%'; const h = el.offsetHeight; el.style.height = h + 'px'; });\n\n// Good: all reads first, then all writes (one layout)\nitems.forEach(el => { el.style.width = '50%'; });\nconst heights = items.map(el => el.offsetHeight);\nitems.forEach((el, i) => { el.style.height = heights[i] + 'px'; });", 'lang': 'js', 'cap': 'Batch reads, then writes'},
  {'code': "// Process a big list without freezing the page: yield every ~8 ms\nconst yieldToMain = () => ('scheduler' in window && 'yield' in scheduler) ? scheduler.yield() : new Promise(r => setTimeout(r, 0));\nasync function processAll(rows, handle) {\n  let start = performance.now();\n  for (const row of rows) {\n    handle(row);\n    if (performance.now() - start > 8) { await yieldToMain(); start = performance.now(); }\n  }\n}\n\n// Find long tasks on any page (paste in the console, then interact)\nnew PerformanceObserver(list => list.getEntries().forEach(e => console.log('long task', Math.round(e.duration), 'ms'))).observe({ type: 'longtask', buffered: true });", 'lang': 'js', 'cap': 'Yielding, and spotting long tasks'},
  {'check': ['Record a performance profile of your slowest interaction and find tasks over 50 ms.', 'Break long work into chunks that yield to the main thread.', 'Move heavy pure computation to a Web Worker.', 'Batch DOM reads before writes; never read layout inside a write loop.', 'Animate only transform and opacity.', 'Add a long-task observer to your real-user monitoring.']},
]

L1 = [
  {'part': 'read'},
  "Rendering strategy is a per-page decision, not a per-app one. A single product often uses all of them: a static marketing site, server-rendered product pages, a client-rendered dashboard. The question for each page is who it is for, how personal it is, how often it changes, and whether search engines need it.",
  {'h': 'Deciding, page by page'},
  {'table': {'head': ['Page', 'Personal?', 'Changes', 'SEO?', 'Choice'], 'rows': [
    ['Landing page, docs, blog', 'No', 'On deploy', 'Yes', 'Static (SSG) on a CDN'],
    ['Product page', 'No (price/stock fetched separately)', 'Minutes', 'Yes', 'ISR or SSR + CDN with a short TTL'],
    ['Search results', 'Partly', 'Every request', 'Somewhat', 'SSR, stream the results'],
    ['Logged-in dashboard', 'Yes', 'Constantly', 'No', 'CSR (or SSR shell + client data)'],
    ['Checkout', 'Yes', 'Every request', 'No', 'SSR or CSR, minimal JavaScript, fast']]}},
  {'h': 'The hydration bill'},
  "SSR makes HTML appear fast, but the page is not interactive until its JavaScript downloads, parses and hydrates. On a mid-range phone, hydrating a large page can take seconds, during which taps do nothing. Ways to pay less: ship less JavaScript, hydrate only interactive parts (islands), hydrate progressively as parts scroll into view, or use server components that never hydrate.",
  {'h': 'Streaming'},
  "Instead of waiting for every data source before sending HTML, the server can flush the page shell immediately and stream slower sections as they are ready. The user sees the header and layout at once and content fills in, which improves perceived speed and LCP when the slow part is not the main content.",
  {'part': 'real'},
  {'case': {'who': 'Netflix', 'when': '2017 and 2018', 'title': 'Removing client-side React from the logged-out homepage',
    'body': ["Netflix's logged-out homepage was rendered with React on the server and hydrated with about 300 KB of JavaScript, including React, Lodash and state data. The team realised the page needed very little interactivity, so they kept React on the server, replaced the client side with a small amount of plain JavaScript, and cut the bundle by about 200 KB. Time to interactive improved by over 50%. They then prefetched React in the background for the following steps of the sign-up flow, which are a single-page app."],
    'lesson': 'Server rendering does not require shipping the framework to the client. Match the JavaScript you send to the interactivity the page actually has.',
    'src': [['A Netflix Web Performance Case Study (Addy Osmani)', 'https://medium.com/dev-channel/a-netflix-web-performance-case-study-c0bcde26a9d9'], ['Netflix functions without client-side React, and it’s a good thing (Jake Archibald)', 'https://jakearchibald.com/2017/netflix-and-react/']]}},
  {'part': 'apply'},
  {'code': "// Next.js (App Router) examples of choosing per page\n\n// app/blog/[slug]/page.tsx  -> static, regenerated at most every hour (ISR)\nexport const revalidate = 3600;\nexport default async function Post({ params }) { const post = await getPost(params.slug); return <Article post={post} />; }\n\n// app/search/page.tsx  -> rendered per request, stream slow results\nexport const dynamic = 'force-dynamic';\nexport default function Search({ searchParams }) {\n  return (<>\n    <SearchHeader q={searchParams.q} />\n    <Suspense fallback={<ResultsSkeleton />}>{/* streamed when ready */}\n      <Results q={searchParams.q} />\n    </Suspense>\n  </>);\n}\n\n// app/dashboard/Chart.tsx  -> only this widget ships JavaScript\n'use client';\nexport function Chart({ data }) { /* interactive chart */ }", 'lang': 'tsx', 'cap': 'Static, streamed and client components in one app'},
  {'check': ['List your page types and fill in: personal? change rate? SEO?', 'Serve anything shared and slow-changing as static or ISR from a CDN.', 'Measure hydration cost on a mid-range phone, not your laptop.', 'Ship JavaScript only for interactive parts (islands, client components).', 'Stream slow sections behind skeletons instead of blocking the whole page.', 'Prefetch the code for the likely next page during idle time.']},
]

L2 = [
  {'part': 'read'},
  "Performance work fails when it is aimed at a score instead of at a user problem. Start from field data: which metric is bad, for which pages, devices and countries. Then use lab tools to find out why. Each Core Web Vital has a short list of usual suspects.",
  {'h': 'Diagnosing each metric'},
  {'table': {'head': ['Metric', 'First questions', 'Usual fixes'], 'rows': [
    ['LCP (load)', 'What is the LCP element? When does its request start? Is TTFB slow?', 'Preload or prioritise the hero image (`fetchpriority=high`), serve modern formats at the right size, cut render-blocking CSS/JS, cache HTML at the edge'],
    ['INP (responsiveness)', 'Which interactions are slow? Is it input delay, handler time, or rendering after?', 'Break up long tasks, reduce re-renders, defer non-urgent work after paint, smaller DOM'],
    ['CLS (stability)', 'What shifted, and what was inserted above it?', 'Set width/height or aspect-ratio on media, reserve space for ads and embeds, `font-display` plus size-adjusted fallbacks']]}},
  {'h': 'A performance budget'},
  "Agree on limits and enforce them in CI: for example, under 170 KB of compressed JavaScript on the critical path for a mobile page, LCP image under 100 KB, no new long tasks over 100 ms in the main flows. Budgets turn 'the site got slow over two years' into a failed build on the day it happened.",
  {'part': 'real'},
  {'case': {'who': 'Vodafone (Italy)', 'when': '2021', 'title': 'A 31% better LCP led to 8% more sales',
    'body': ["Vodafone ran an A/B test on a landing page where the only difference was that version A was optimised for Web Vitals, measuring LCP on real user sessions. Version A had a 31% better LCP in the field and produced 8% more sales, a 15% better lead-to-visit rate and an 11% better cart-to-visit rate. The changes included server-side rendering critical HTML, reducing render-blocking JavaScript and optimising images."],
    'lesson': 'Performance has measurable business value. An A/B test with field metrics is the most convincing way to show it.',
    'src': [['Vodafone: A 31% improvement in LCP increased sales by 8% (web.dev)', 'https://web.dev/case-studies/vodafone']]}},
  {'case': {'who': 'Pinterest', 'when': '2017', 'title': 'Rebuilding the mobile web as a fast progressive web app',
    'body': ["Pinterest rebuilt its mobile web experience as a progressive web app, focusing on a small initial JavaScript bundle with route-based code splitting, a service worker for caching, and careful image loading. Addy Osmani's case study reports large reductions in time to interactive and core bundle size, and big increases in engagement metrics compared with the old mobile site."],
    'lesson': 'Code splitting and caching the app shell change how a site feels on real phones and networks.',
    'src': [['A Pinterest Progressive Web App Performance Case Study', 'https://medium.com/dev-channel/a-pinterest-progressive-web-app-performance-case-study-3bd6ed2e6154']]}},
  {'part': 'apply'},
  {'code': "// Real-user Core Web Vitals with the web-vitals library, sent to your analytics\nimport { onLCP, onINP, onCLS, onTTFB } from 'web-vitals/attribution';\nfunction send(metric) {\n  navigator.sendBeacon('/rum', JSON.stringify({\n    name: metric.name, value: Math.round(metric.value), rating: metric.rating,\n    page: location.pathname, // add device class, connection, country server-side\n    target: metric.attribution?.target || metric.attribution?.interactionTarget || metric.attribution?.largestShiftTarget,\n  }));\n}\nonLCP(send); onINP(send); onCLS(send); onTTFB(send);", 'lang': 'js', 'cap': 'Field data first, with attribution so you know what to fix'},
  {'code': "<!-- The hero image: discovered early, high priority, right size, no layout shift -->\n<link rel=\"preload\" as=\"image\" href=\"/hero-1200.avif\" imagesrcset=\"/hero-600.avif 600w, /hero-1200.avif 1200w\" imagesizes=\"100vw\" fetchpriority=\"high\">\n<img src=\"/hero-1200.avif\" srcset=\"/hero-600.avif 600w, /hero-1200.avif 1200w\" sizes=\"100vw\"\n     width=\"1200\" height=\"600\" fetchpriority=\"high\" alt=\"Summer collection\">\n<!-- below the fold: lazy -->\n<img src=\"/card.avif\" loading=\"lazy\" width=\"400\" height=\"300\" alt=\"\">", 'lang': 'html', 'cap': 'LCP and CLS fixes in markup'},
  {'check': ['Collect field Core Web Vitals (RUM) by page type and device class.', 'For the worst metric, find the element or interaction responsible using attribution.', 'Prioritise the LCP resource and size images properly.', 'Reserve space for everything that loads late.', 'Set a performance budget and enforce it in CI (bundle size, Lighthouse CI).', 'Re-check field data after each release.']},
]

L3 = [
  {'part': 'read'},
  "Storage in the browser is not one thing: cookies travel with every request, localStorage is synchronous and blocks the main thread, IndexedDB is asynchronous and large, the Cache API stores HTTP responses for service workers. Pick by what the data is and who needs it.",
  {'h': 'Choosing'},
  {'table': {'head': ['Data', 'Store', 'Why'], 'rows': [
    ['Session or auth token', 'HttpOnly cookie', 'Script cannot read it, so XSS cannot steal it'],
    ['Small UI preference (theme)', 'localStorage', 'Simple, tiny, read once at startup'],
    ['Drafts, offline data, large lists', 'IndexedDB', 'Async, structured, large, works in workers'],
    ['App shell, assets, API responses for offline', 'Cache API via a service worker', 'Serves requests without the network'],
    ['Anything sensitive', 'Nowhere persistent if avoidable', 'Shared computers and XSS']]}},
  {'h': 'Service worker caching strategies'},
  {'ul': ['**Cache first** for versioned static assets: instant, and new versions have new URLs.', '**Network first, cache fallback** for HTML or API data that should be fresh but must work offline.', '**Stale-while-revalidate** for things where speed matters more than freshness (avatars, non-critical data).', 'Always version the cache and delete old ones in the `activate` event, or users get stuck on old code.']},
  {'h': 'Storage can disappear'},
  "Browsers may evict storage under disk pressure, users clear it, and some browsers cap how long script-written storage lives without user interaction. Treat client storage as a cache of server data, ask for persistent storage (`navigator.storage.persist()`) for important offline data, and sync to the server as the source of truth.",
  {'part': 'real'},
  {'case': {'who': 'Twitter', 'when': '2017', 'title': 'Twitter Lite: a progressive web app',
    'body': ["Twitter built Twitter Lite as a progressive web app for mobile browsers, aimed at slow networks and low-end devices. A service worker cached the app shell and assets so repeat visits loaded quickly and parts of the app worked offline, and the team invested heavily in small route-based bundles and data saving options. Twitter's engineering post describes the performance techniques in detail."],
    'lesson': 'A service worker turns repeat visits into near-instant loads. Design the app shell and caching strategy from the start.',
    'src': [['How we built Twitter Lite (Twitter Engineering)', 'https://blog.twitter.com/2017/how-we-built-twitter-lite'], ['Twitter Lite PWA case study (web.dev)', 'https://web.dev/case-studies/twitter']]}},
  {'case': {'who': 'WebKit (Safari)', 'when': '2020', 'title': 'A 7-day cap on script-writable storage',
    'body': ["As part of Intelligent Tracking Prevention, Safari began deleting all script-writable storage (localStorage, IndexedDB, service worker registrations and more) for a website after seven days of Safari use without user interaction on that site. Installed home screen web apps were treated differently. The change was aimed at tracking, but it affects any app that assumes client storage lasts forever."],
    'lesson': 'Client-side storage is a cache, not a database. Keep the source of truth on the server.',
    'src': [['Full Third-Party Cookie Blocking and More (WebKit)', 'https://webkit.org/blog/10218/full-third-party-cookie-blocking-and-more/']]}},
  {'part': 'apply'},
  {'code': "// sw.js: versioned caches, cache-first for assets, network-first for pages\nconst VERSION = 'v42', ASSETS = `assets-${VERSION}`, PAGES = `pages-${VERSION}`;\nself.addEventListener('install', e => e.waitUntil(caches.open(ASSETS).then(c => c.addAll(['/', '/app.css', '/app.js', '/offline.html']))));\nself.addEventListener('activate', e => e.waitUntil(\n  caches.keys().then(keys => Promise.all(keys.filter(k => !k.endsWith(VERSION)).map(k => caches.delete(k))))));\nself.addEventListener('fetch', e => {\n  const url = new URL(e.request.url);\n  if (url.pathname.startsWith('/assets/')) {\n    e.respondWith(caches.match(e.request).then(hit => hit || fetch(e.request).then(res => {\n      const copy = res.clone(); caches.open(ASSETS).then(c => c.put(e.request, copy)); return res; })));\n  } else if (e.request.mode === 'navigate') {\n    e.respondWith(fetch(e.request).then(res => { const copy = res.clone(); caches.open(PAGES).then(c => c.put(e.request, copy)); return res; })\n      .catch(() => caches.match(e.request).then(hit => hit || caches.match('/offline.html'))));\n  }\n});", 'lang': 'js', 'cap': 'A service worker you can adapt'},
  {'check': ['Keep auth in HttpOnly cookies, never in localStorage.', 'Use IndexedDB (via a small wrapper) for anything large or structured.', 'Cache static assets cache-first with versioned names.', 'Use network-first with an offline fallback for pages.', 'Delete old caches on activate and test updates.', 'Treat local data as a cache and sync it to the server.']},
]

L4 = [
  {'part': 'read'},
  "Most framework performance problems are not about the framework being slow; they are about doing work that did not need doing: re-rendering components whose output did not change, recomputing expensive values every render, or rendering thousands of rows nobody can see.",
  {'h': 'Finding unnecessary renders'},
  "Use the React DevTools Profiler (or your framework's equivalent) and record the slow interaction. Look for components that rendered but produced the same output, and for one state change that re-renders a large subtree. The usual causes: state held too high, a context value that is a new object every render, inline objects and functions passed as props to memoised children, and effects that set state after every render.",
  {'h': 'Fixes in order of preference'},
  {'ol': ['**Move state down** to the component that uses it, so changes re-render less.', '**Lift content up:** pass children as props so they are not re-rendered by the parent’s state changes.', '**Derive instead of syncing:** compute values during render instead of copying them into state with effects.', '**Split contexts** so consumers only re-render for the values they use.', '**Memoise** expensive computations (`useMemo`) and stable callbacks for memoised children, but only after measuring.', '**Virtualise** long lists so only visible rows exist.', '**Defer** non-urgent updates (`useDeferredValue`, `startTransition`) so typing stays responsive.']},
  {'part': 'real'},
  {'case': {'who': 'Discord', 'when': '2019', 'title': 'Native-feeling performance with React Native on iOS',
    'body': ["Discord described how it kept its React Native iOS app fast as features grew. Much of the work was about avoiding unnecessary rendering: profiling which components re-rendered, memoising list rows, reducing work done while scrolling and moving expensive work out of the render path, plus a custom high-performance list. Their point was that the framework was rarely the bottleneck; wasted renders were."],
    'lesson': 'Profile, then remove wasted renders. Memoisation and list virtualisation are the biggest levers in component-based UIs.',
    'src': [['How Discord achieves native iOS performance with React Native', 'https://discord.com/blog/how-discord-achieves-native-ios-performance-with-react-native']]}},
  {'case': {'who': 'React team', 'when': 'react.dev', 'title': 'You might not need an effect',
    'body': ["The React documentation lists common cases where developers use effects unnecessarily: computing derived data, resetting state when a prop changes, or chaining state updates. Each causes an extra render and can create bugs. The recommended alternatives (compute during render, use a key to reset, handle logic in event handlers) are simpler and faster."],
    'lesson': 'Every effect that sets state causes another render. Derive values during render whenever you can.',
    'src': [['You Might Not Need an Effect (react.dev)', 'https://react.dev/learn/you-might-not-need-an-effect']]}},
  {'part': 'apply'},
  {'code': "// Typing in a search box made a 5,000-row table laggy. Fixes, in order:\nfunction Page({ rows }) {\n  const [query, setQuery] = useState('');\n  const deferred = useDeferredValue(query);                    // typing stays urgent, filtering can lag\n  const visible = useMemo(\n    () => rows.filter(r => r.name.toLowerCase().includes(deferred.toLowerCase())),\n    [rows, deferred]);                                           // recompute only when inputs change\n  return (<>\n    <input value={query} onChange={e => setQuery(e.target.value)} />\n    <VirtualTable rows={visible} rowHeight={36} />{/* only ~30 rows in the DOM */}\n  </>);\n}\nconst Row = memo(function Row({ row }) { return <div className=\"row\">{row.name}</div>; });\n\n// Instead of syncing derived state with an effect:\n// const [fullName, setFullName] = useState(''); useEffect(() => setFullName(first + ' ' + last), [first, last]);\nconst fullName = `${first} ${last}`;                          // just compute it", 'lang': 'jsx', 'cap': 'Defer, memoise, virtualise, derive'},
  {'check': ['Profile the slow interaction before changing code.', 'Move state down to where it is used.', 'Remove effects that only derive or sync state.', 'Split large contexts; keep context values stable.', 'Virtualise lists over a few hundred rows.', 'Use deferred values or transitions for expensive updates caused by typing.']},
]

LESSONS = [L0, L1, L2, L3, L4]
